pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract with a fuzzed amount (its Owner is this test contract)
        vm.deal(address(c), amount);

        // call withdraw() from the Owner with zero msg.value; admissible: succeeds in P
        vm.prank(address(this));
        c.withdraw();

        // Rule: after any successful withdraw(), the contract balance is fully drained to the Owner.
        assertTrue(address(c).balance == 0);
    }
}

