pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit, uint256 callValue) public {
        deposit = bound(deposit, 1, 1e30);
        callValue = bound(callValue, 0, 1e30);

        // fund the contract directly (simulates prior deposits)
        vm.deal(address(c), deposit);
        // give the caller (the Owner/deployer) the ETH to attach to withdraw
        vm.deal(address(this), callValue);

        bool ok;
        try c.withdraw{value: callValue}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever withdraw() succeeds, the contract's ENTIRE
        // balance is transferred out, so its balance must be 0.
        assertTrue(!ok || address(c).balance == 0);
    }
}

