pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        // Fund the contract directly so a withdrawal has something to move.
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;

        // Only the Owner may withdraw; drive c through withdraw as the Owner.
        vm.prank(c.Owner());
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // Rule: a successful withdraw by the Owner always empties the contract
        // (the entire held balance is transferred out). The mutant, having no
        // transfer, succeeds but leaves the full balance inside.
        assertTrue(ok && (before == 0 || address(c).balance == 0));
    }
}

