pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the funded amount admissible (avoids overflow-adjacent extremes)
        amount = bound(amount, 1 wei, 1e30 ether);

        // fund the contract directly so no adversarial counterparty is needed
        vm.deal(address(c), amount);

        // the deployer (this test contract) is the Owner
        vm.prank(address(this));
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY balance the contract holds, a successful owner
        // withdrawal empties the contract's balance entirely.
        // Reference: always ok and balance 0. Mutant: transfer deleted -> balance stays amount.
        assertTrue(ok && address(c).balance == 0);
    }
}

