pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        // The Owner of c is the deployer (this test contract). To make the
        // owner a party that CANNOT receive Ether (so P's transfer to Owner
        // fails), we deploy a fresh C from a code-bearing no-receiver helper:
        // then the helper is Owner and any ETH transfer to it reverts.
        NoReceiver ownerHelper = new NoReceiver();
        C target;
        address prev = msg.sender;
        vm.startPrank(address(ownerHelper));
        target = new C();
        vm.stopPrank();
        (prev);

        vm.deal(address(target), amount);

        bool ok;
        vm.prank(address(ownerHelper));
        try target.withdraw() { ok = true; } catch { ok = false; }

        // Rule: withdrawing the whole balance to an Owner that cannot accept
        // ETH must fail; the mutant (no transfer) makes withdraw succeed.
        assertTrue(ok == false);
    }
}

contract NoReceiver {
    // intentionally has no receive/fallback: ETH transfers to it revert
    constructor() {}
}

