pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Recipient r;

    function setUp() public { c = new C(); r = new Recipient(); }

    function testFuzz_property(uint256 preFund, uint256 amount) public {
        preFund = bound(preFund, 1, 1000 ether);
        amount = bound(amount, 0, preFund);

        address actor = address(0xABCD);

        // pre-fund the contract with extra ether held by nobody's call
        vm.deal(actor, preFund + amount);
        vm.prank(actor);
        (bool okFwd, ) = address(c).call{value: preFund}("");
        assertTrue(okFwd);

        uint256 before = address(c).balance;
        uint256 recipBefore = address(r).balance;

        // drive Command with msg.value = amount (< before, so mutant drains extra)
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Command(address(r), "");

        // Rule: Command forwards only msg.value, so c retains before - amount.
        assertTrue(
            address(c).balance == before - amount &&
            address(r).balance == recipBefore + amount
        );
    }
}

contract Recipient {
    receive() external payable {}
    fallback() external payable {}
}

