pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address actor;

    function setUp() public {
        c = new C();
        actor = address(0xA11CE);
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(data.length > 0);
        amount = bound(amount, 1, 1 ether);

        // adversarial counterparty: accepts ether ONLY when calldata is non-empty
        FallbackOnly helper = new FallbackOnly();

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Command{value: amount}(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: Command with arbitrary non-empty calldata to a callee whose
        // payable fallback accepts value must complete without reverting.
        assertTrue(ok);
    }
}

contract FallbackOnly {
    receive() external payable {
        revert("no bare transfer");
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        return "ok";
    }
}

