pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = c.Owner();
    }

    function testFuzz_property(uint256 helperAmt, uint256 msgVal, bytes32 seed) public {
        helperAmt = bound(helperAmt, 1, type(uint128).max);
        msgVal = bound(msgVal, 0, type(uint128).max);

        // Adversarial helper: holds ether and, when invoked, selfdestructs its
        // whole balance to c. It has NO payable fallback/receive.
        Boom boom = new Boom(address(c));
        vm.deal(address(boom), helperAmt);

        vm.deal(owner, msgVal);
        uint256 before = address(c).balance;
        bytes memory data = abi.encodeWithSelector(boom.boom.selector, seed);

        bool ok;
        vm.prank(owner);
        try c.Command{value: msgVal}(address(boom), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C ignores the low-level call's outcome and its calldata
        // (boom's selfdestruct) fires, so c's balance grows by helperAmt and
        // Command succeeds. The mutant discards the calldata and bare-transfers
        // to a contract with no payable fallback, reverting and leaving c's
        // balance unchanged.
        assertTrue(ok && address(c).balance == before + helperAmt);
    }
}

contract Boom {
    address payable target;
    constructor(address t) { target = payable(t); }
    function boom(bytes32) external { selfdestruct(target); }
}

