pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedFund, uint256 amount, address actor) public {
        // give c a wide fuzzed starting balance
        vm.deal(address(c), bound(seedFund, 1 ether, 1e9 ether));
        // msg.value strictly below the contract balance: the guard must fail
        amount = bound(amount, 1 wei, address(c).balance - 1);
        vm.deal(actor, amount);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.multiplicate{value: amount}(actor);
        // Rule: a call with msg.value < balance does not change c's balance
        assertTrue(address(c).balance == balBefore, "balance must be preserved when guard fails");
    }
}

